-- T001 of specs/004-sessions/tasks.md: the sessions pass (specs/004-sessions/data-model.md §2.1 to
-- §2.12 and §6; ERD v1.15). Generated by `prisma migrate diff --from-config-datasource --to-schema
-- prisma/schema --script` against a database holding every migration before it, then extended by
-- hand for what the schema language cannot say.
--
-- What it lands: `sessions.outcome_under_dispute` and `admin_settled_at` (§2.1); the room-ended
-- event, a nullable participant and the connection's reference on `session_participant_events`
-- (§2.2), altered as the owner, the table's UPDATE, DELETE and TRUNCATE staying revoked from the
-- application role (rule 21); the offer, its two snapshots and the pending counter-proposal on
-- `session_remedies` (§2.3), whose status gains `frozen` and `lapsed`; the append-only tables
-- `session_events` (§2.4) and `provider_outages` (§2.5); `enrollment_event_kind`'s three outcomes
-- (§2.8); the complaint's kind and resolution on `disputes` (§2.7); `slot_holds.release_reason`
-- (§2.12), NULL on every hold released before it; ERD §15 rules 40 to 48; and the deletion of the
-- `teacher_no_show_threshold` setting, the threshold removed (R-322, ADR 0023). `session_remedies`
-- held no row when this was written (nothing wrote it before Phase 3), so its four NOT NULL columns
-- are added without a default. No index beyond the foreign keys' plain indexes and the three
-- partial uniques of rules 45 and 46 (R-DB-9).
--
-- WHY A COMMIT AFTER THE ENUM VALUES. PostgreSQL refuses a value added by `ALTER TYPE ... ADD VALUE`
-- in the transaction that added it ("unsafe use of new value", 55P04: it must be committed first),
-- and rules 41 and 46 name `room_ended`, `absence_complaint` and `enrollment_ended`. The script runs
-- as one implicit transaction, so the values are committed first and the rest runs in a second
-- one. Each value is added `IF NOT EXISTS`: if the second part is ever refused (rule 46 counts the
-- `disputes` rows it would refuse before it runs on a database with rows, data-model.md §6), the
-- migration is marked rolled back, the rows answered, and the whole script runs again unchanged.

-- AlterEnum
ALTER TYPE "dispute_kind" ADD VALUE IF NOT EXISTS 'absence_complaint';

-- AlterEnum
ALTER TYPE "dispute_resolution" ADD VALUE IF NOT EXISTS 'enrollment_ended';

-- AlterEnum
ALTER TYPE "enrollment_event_kind" ADD VALUE IF NOT EXISTS 'completed';
ALTER TYPE "enrollment_event_kind" ADD VALUE IF NOT EXISTS 'terminated_no_show';
ALTER TYPE "enrollment_event_kind" ADD VALUE IF NOT EXISTS 'restored';

-- AlterEnum
ALTER TYPE "participant_event_type" ADD VALUE IF NOT EXISTS 'room_ended';

-- AlterEnum
ALTER TYPE "remedy_status" ADD VALUE IF NOT EXISTS 'frozen';
ALTER TYPE "remedy_status" ADD VALUE IF NOT EXISTS 'lapsed';

-- The values above are committed before any statement below uses them (see the header).
COMMIT;

-- CreateEnum
CREATE TYPE "hold_release_reason" AS ENUM ('converted', 'expired', 'checkout_abandoned', 'slot_unavailable', 'admin', 'teacher_suspended', 'account_deleted');

-- CreateEnum
CREATE TYPE "session_event_kind" AS ENUM ('settled', 'cancellation_requested', 'cancellation_accepted', 'cancellation_declined', 'cancellation_expired', 'cancelled_by_admin', 'remedy_offered', 'counter_proposed', 'counter_accepted', 'counter_declined', 'counter_withdrawn', 'remedy_frozen', 'makeup_booked', 'remedy_handed_to_case', 'remedy_lapsed', 'dispute_raised', 'dispute_resolved', 'dispute_revised', 'review_resolved', 'outage_reclassified', 'complaint_raised', 'complaint_decided', 'outcome_corrected', 'instants_reresolved', 'counter_booking_refused');

