ALTER TABLE "session_participant_events" ADD COLUMN     "connection_ref" TEXT,
ALTER COLUMN "user_id" DROP NOT NULL;

-- AlterTable
ALTER TABLE "session_remedies" ADD COLUMN     "choice_closes_at" TIMESTAMPTZ(6) NOT NULL,
ADD COLUMN     "counter_proposed_at" TIMESTAMPTZ(6),
ADD COLUMN     "counter_slot_id" UUID,
ADD COLUMN     "counter_start_time_local" TIME(0),
ADD COLUMN     "counter_timezone" TEXT,
ADD COLUMN     "offered_at" TIMESTAMPTZ(6) NOT NULL,
ADD COLUMN     "snapshot_answer_window_hours" INTEGER NOT NULL,
