CREATE INDEX "session_events_session_id_idx" ON "session_events"("session_id");

-- CreateIndex
CREATE INDEX "session_events_case_id_idx" ON "session_events"("case_id");

-- CreateIndex
CREATE INDEX "session_events_counter_slot_id_idx" ON "session_events"("counter_slot_id");

