ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_counter_slot_id_fkey" FOREIGN KEY ("counter_slot_id") REFERENCES "availability_slots"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

