-- Hand-written: what the schema language cannot say.

-- Rule 40: a frozen outcome only while the session is disputed, and then one of the six outcomes
-- the evaluation or a review could have written (FR-DISPUTE-4); NULL while a dispute raised before
-- the evaluation waits for it. An administrator's settling carries its instant (FR-450).
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_outcome_under_dispute_check"
    CHECK ("outcome_under_dispute" IS NULL
        OR ("status" = 'disputed'
            AND "outcome_under_dispute" IN ('done', 'student_no_show', 'teacher_no_show',
                                            'both_no_show', 'under_threshold', 'provider_outage')));

ALTER TABLE "sessions" ADD CONSTRAINT "sessions_admin_settled_check"
    CHECK (("settled_by_admin_id" IS NULL) = ("admin_settled_at" IS NULL));

-- Rule 41: a participant's event names its participant and its connection; the room's end, which
-- closes every connection still open, names neither (FR-443, R-304).
ALTER TABLE "session_participant_events" ADD CONSTRAINT "session_participant_events_user_id_check"
    CHECK (("event_type" = 'room_ended') = ("user_id" IS NULL));

ALTER TABLE "session_participant_events" ADD CONSTRAINT "session_participant_events_connection_ref_check"
    CHECK (("event_type" = 'room_ended') = ("connection_ref" IS NULL));

-- Rule 42: the five columns of the pending counter-proposal are all set exactly while it is pending
-- (the owner's decision 9 of 2026-11-05); a case exactly on a remedy handed to one, so a lapsed
-- remedy has none; the choice window closes after the offer; the two snapshots in range (FR-465).
ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_counter_check"
    CHECK (num_nonnulls("counter_date", "counter_slot_id", "counter_start_time_local",
                        "counter_timezone", "counter_proposed_at")
           = CASE WHEN "status" = 'counter_proposed' THEN 5 ELSE 0 END);

ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_case_check"
    CHECK (("status" = 'refund_case') = ("case_id" IS NOT NULL));

ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_choice_window_check"
    CHECK ("choice_closes_at" > "offered_at");

ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_answer_window_check"
    CHECK ("snapshot_answer_window_hours" > 0);

ALTER TABLE "session_remedies" ADD CONSTRAINT "session_remedies_first_session_lead_check"
    CHECK ("snapshot_first_session_lead_hours" >= 0);

-- Rule 43: a session event says one thing per kind. The counter-proposal's four columns exactly on
-- `counter_proposed`; a case only on the four kinds that name one, and always on a revision and a
-- complaint; no session exactly on the two complaint kinds (R-322); both outcomes exactly on a
-- revision and a correction, each one of the four (R-308, R-323 GAP-3); the previous start exactly
-- on a re-resolution (R-323 GAP-6).
ALTER TABLE "session_events" ADD CONSTRAINT "session_events_counter_check"
    CHECK (num_nonnulls("counter_slot_id", "counter_date", "counter_start_time_local",
                        "counter_timezone")
           = CASE WHEN "kind" = 'counter_proposed' THEN 4 ELSE 0 END);

ALTER TABLE "session_events" ADD CONSTRAINT "session_events_case_check"
    CHECK (("case_id" IS NULL
            OR "kind" IN ('cancelled_by_admin', 'dispute_revised', 'complaint_raised',
                          'complaint_decided'))
           AND ("case_id" IS NOT NULL
                OR "kind" NOT IN ('dispute_revised', 'complaint_raised', 'complaint_decided')));

ALTER TABLE "session_events" ADD CONSTRAINT "session_events_session_check"
    CHECK (("kind" IN ('complaint_raised', 'complaint_decided')) = ("session_id" IS NULL));

ALTER TABLE "session_events" ADD CONSTRAINT "session_events_outcome_check"
    CHECK (num_nonnulls("outcome_before", "outcome_after")
             = CASE WHEN "kind" IN ('dispute_revised', 'outcome_corrected') THEN 2 ELSE 0 END
           AND ("outcome_before" IS NULL
                OR "outcome_before" IN ('done', 'student_no_show', 'teacher_no_show', 'both_no_show'))
           AND ("outcome_after" IS NULL
                OR "outcome_after" IN ('done', 'student_no_show', 'teacher_no_show', 'both_no_show')));

ALTER TABLE "session_events" ADD CONSTRAINT "session_events_previous_start_check"
    CHECK (("kind" = 'instants_reresolved') = ("previous_start_at" IS NOT NULL));

-- Rule 43: the row records something that happened, so the application role may not rewrite or
-- remove it (rule 21's pattern); its foreign keys are RESTRICT on update above.
REVOKE UPDATE, DELETE, TRUNCATE ON "session_events" FROM ijazah_app;

-- Rule 44: a video outage window ends after it starts, and is evidence the application role may not
-- rewrite or remove (R-307).
ALTER TABLE "provider_outages" ADD CONSTRAINT "provider_outages_window_check"
    CHECK ("ends_at" > "starts_at");

REVOKE UPDATE, DELETE, TRUNCATE ON "provider_outages" FROM ijazah_app;

-- Rule 45: one pending cancellation request per session (FR-456), an answer's instant exactly on an
-- accepted or declined request, and a reason that is not blank (FR-CANCEL-1).
CREATE UNIQUE INDEX "cancellation_requests_one_pending_key" ON "cancellation_requests"("session_id")
    WHERE "status" = 'pending';

ALTER TABLE "cancellation_requests" ADD CONSTRAINT "cancellation_requests_responded_at_check"
    CHECK (("status" IN ('accepted', 'declined')) = ("responded_at" IS NOT NULL));

ALTER TABLE "cancellation_requests" ADD CONSTRAINT "cancellation_requests_reason_check"
    CHECK (length(btrim("reason")) > 0);

-- Rule 46: one open session dispute per session (FR-473) and one open complaint per enrollment
-- (FR-452); a session exactly on a session dispute; a closing instant exactly on a closed row,
-- which carries its notes and its administrator (FR-422); a complaint raised by its student; an
-- ended enrollment only as a complaint's resolution (R-322, ADR 0023).
CREATE UNIQUE INDEX "disputes_one_open_per_session_key" ON "disputes"("session_id")
    WHERE "kind" = 'session_dispute' AND "status" = 'open';

CREATE UNIQUE INDEX "disputes_one_open_complaint_per_enrollment_key" ON "disputes"("enrollment_id")
    WHERE "kind" = 'absence_complaint' AND "status" = 'open';

ALTER TABLE "disputes" ADD CONSTRAINT "disputes_session_check"
    CHECK (("kind" = 'session_dispute') = ("session_id" IS NOT NULL));

ALTER TABLE "disputes" ADD CONSTRAINT "disputes_resolved_at_check"
    CHECK (("status" = 'open') = ("resolved_at" IS NULL));

ALTER TABLE "disputes" ADD CONSTRAINT "disputes_closed_check"
    CHECK ("status" = 'open'
        OR ("resolution_notes" IS NOT NULL AND "resolved_by_admin_id" IS NOT NULL));

ALTER TABLE "disputes" ADD CONSTRAINT "disputes_complaint_raiser_check"
    CHECK ("kind" <> 'absence_complaint' OR "raised_by_user_id" IS NOT NULL);

ALTER TABLE "disputes" ADD CONSTRAINT "disputes_enrollment_ended_check"
    CHECK ("resolution" IS DISTINCT FROM 'enrollment_ended' OR "kind" = 'absence_complaint');

-- Rule 47: a chat attachment is a PDF or plain text (FR-SESS-7 as amended on 2026-11-05), and its
-- three columns are all set or all NULL unless the retention purge nulled them (rule 8 beside it).
ALTER TABLE "chat_messages" ADD CONSTRAINT "chat_messages_attachment_mime_check"
    CHECK ("attachment_mime" IS NULL OR "attachment_mime" IN ('application/pdf', 'text/plain'));

ALTER TABLE "chat_messages" ADD CONSTRAINT "chat_messages_attachment_check"
    CHECK ("purged_at" IS NOT NULL
        OR num_nonnulls("attachment_key", "attachment_filename", "attachment_mime") IN (0, 3));

-- Rule 48: a release reason only on a released hold (R-323 GAP-8).
ALTER TABLE "slot_holds" ADD CONSTRAINT "slot_holds_release_reason_check"
    CHECK ("release_reason" IS NULL OR "released_at" IS NOT NULL);

-- The threshold is removed with automatic termination (R-322, ADR 0023); the seed no longer writes
-- it (data-model.md §4).
DELETE FROM "settings" WHERE "key" = 'teacher_no_show_threshold';
